import re
from pathlib import Path

import pytest

import trudag.score as score
from trudag.dotstop.core.graph import TrustableGraph
from trudag.dotstop.core.validator import Validator
from trudag.publish import publish


def replace_datetime_dot_now(markdown_str: str):
    return re.sub(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(.\d{6})?", "NOW", markdown_str)


class MockDataStoreClient:
    def pull(self) -> list[dict]:
        return [
            {
                "scores": [
                    {"id": "EXP-1", "score": 0.69},
                    {"id": "ASN-2", "score": 0.69},
                    {"id": "ASN-1", "score": 0.69},
                    {"id": "ASN-3", "score": 0.50},
                    {"id": "TST-1", "score": 0.50},
                ],
                "info": {
                    "Commit date/time": 1749612000,
                    "Commit SHA": "test",
                    "Commit tag": "test",
                    "Repository root": "test",
                    "CI job id": "test",
                    "Schema version": "test",
                    "Branch name": "test",
                },
            }
        ]


@pytest.fixture
def make_report(tmp_path: Path, test_workspace: dict):
    scores = score.score(test_workspace["graph"], validator=Validator())
    publish(
        graph=test_workspace["graph"],
        project_name=test_workspace["report"]["name"],
        all_bodies=True,
        output_path=tmp_path,
        validator=Validator(),
        scores=scores,
    )
    return tmp_path


@pytest.fixture
def make_report_sensitivity(tmp_path: Path, test_workspace: dict):
    publish(
        graph=test_workspace["graph"],
        project_name=test_workspace["report"]["name"],
        all_bodies=True,
        output_path=tmp_path,
        validator=Validator(),
        scores={item.name: (0, "Missing") for item in test_workspace["graph"].items},
        sensitivity=score.item_sensitivity(test_workspace["graph"]),
    )
    return tmp_path


@pytest.fixture
def make_report_figures(tmp_path: Path, test_workspace: dict):
    scores = score.score(test_workspace["graph"], validator=Validator())
    publish(
        graph=test_workspace["graph"],
        project_name=test_workspace["report"]["name"],
        all_bodies=True,
        output_path=tmp_path,
        validator=Validator(),
        figures=True,
        data_store_client=MockDataStoreClient(),
        scores=scores,
    )
    return tmp_path


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace", "empty_workspace"],
    indirect=True,
)
def test_report_figures(make_report_figures, monkeypatch, test_workspace: dict):
    monkeypatch.chdir(make_report_figures)
    for file, expected in test_workspace["report"]["figures"]:
        assert (
            replace_datetime_dot_now((make_report_figures / file).read_text())
            == expected()
        )


