@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_log_changed_non_normative(test_workspace: dict, caplog, tmp_path: Path):
    graph: TrustableGraph = test_workspace["graph"]
    item_to_change = "TST-1"
    assert graph.get_item(item_to_change).normative
    graph.get_item(item_to_change)._normative = False  # noqa SLF001
    graph.set_review_status(item_to_change, True)
    assert not graph.get_item(item_to_change).normative
    publish(
        graph=graph,
        project_name=test_workspace["report"]["name"],
        all_bodies=True,
        output_path=tmp_path,
        validator=Validator(),
        scores={item.name: (0, "Missing") for item in graph.items},
        figures=True,
        data_store_client=MockDataStoreClient(),
    )
    expected_log = (
        "Ignoring TST-1 in historic data transformation, it is no longer normative"
    )
    assert any(log == expected_log for log in caplog.messages)


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace", "empty_workspace"],
    indirect=True,
)
def test_sensitivity(make_report_sensitivity, tmp_path: Path, test_workspace: dict):
    """
    Test for the following graph:

                                ┌─────┐
                             ┌──│EXP-1├──┐
                             │  └─────┘  │
                             │           │
                             │           │
                          ┌──▼──┐     ┌──▼──┐
           ┌───────────┬──┤ASN-1├─┐ ┌─┤ASN-2├──┐
           │           │  └─────┘ │ │ └─────┘  │
           │           │          │ │          │
           │           │          │ │          │
        ┌──▼──┐     ┌──▼──┐     ┌─▼─▼─┐     ┌──▼──┐
        │TST-1│     │TST-2│     │DOC-1│     │TST-3│
        └─────┘     └─────┘     └─────┘     └─────┘

    Where we confirm that we can't get any sensitivity analysis for premises (TST.md, DOC.md)
    and we get sensitivity analysis for non-premise items (EXP.md, ASN.md).
    """
    # check for lack of sensitivities inside premise items
    for document in test_workspace["graph"].get_premises():
        assert (
            "**Sensitivity Analysis:**"
            not in (tmp_path / f"{document.document}.md").read_text()
        )

    # check for sensitivities inside non-premise items
    non_premise_texts = "".join(
        [
            (tmp_path / f"{item.document}.md").read_text()
            for item in (
                set(test_workspace["graph"].items)
                - set(test_workspace["graph"].get_premises())
            )
        ]
    )

    for sensitivity in test_workspace["report"]["sensitivities"]:
        assert sensitivity in non_premise_texts
